def find_path(graph, start, goal):
    visited = set()  # To keep track of visited nodes to avoid cycles
    path = []  # List to store the path

    def explore(node):
        """Depth-first exploration of the graph from a given node."""
        if node == goal:
            path.append(node)  # Append the goal node to the path
            path.reverse()  # Reverse the path to get from start to goal
            return True
        visited.add(node)  # Mark the node as visited
        path.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if explore(neighbor):
                    return True
        path.pop()  # Remove the last node if the neighbor exploration fails
        return False

    if start not in graph or goal not in graph:
        return None
    explore(start)
    return path if len(path) > 1 else None
