def find_path(graph, start, goal):
    # Initialize the path and the visited set
    path = []
    visited = set()

    def explore(node):
        if node in visited:
            return False
        visited.add(node)
        if node == goal:
            return True
        for neighbor in graph.get(node, []):
            if explore(neighbor):
                path.append(node)
                return True
        return False

    if start not in graph:
        return None

    explore(start)
    # If the goal was not reached, return None
    if len(path) == 0:
        return None
    # Otherwise, return the path from start to goal
    return path[::-1]
