def find_path(graph, start, goal):
    # Initialize the path and a set to keep track of visited nodes
    path = []
    visited = set()

    # Create a queue for the breadth-first search
    from collections import deque
    queue = deque([(start, [start])])

    while queue:
        (current_node, path_so_far) = queue.popleft()
        if current_node not in visited:
            visited.add(current_node)
            if current_node == goal:
                return path_so_far
            for next_node in graph.get(current_node, []):
                if next_node not in visited:
                    queue.append((next_node, path_so_far + [next_node]))

    # If we reach here, it means the goal is unreachable
    return None
