def find_path(graph, start, goal):
    def explore(remaining_path):
        node = remaining_path[-1]
        if node == goal:
            return remaining_path
        for neighbor in graph.get(node, []):
            if neighbor not in remaining_path:
                new_path = explore(remaining_path + [neighbor])
                if new_path:
                    return new_path
        return None

    return explore([start])
